import {
	Component,
	Element,
	Event,
	EventEmitter,
	Prop,
	h,
} from "@stencil/core";
import { testSlot } from "../../utils/slot";

/**
 * @since 0.0.6
 * @status beta
 *
 * @slot - The breadcrumb item's label.
 * @slot prefix - An optional prefix, usually an icon or icon button.
 * @slot suffix - An optional suffix, usually an icon or icon button.
 * @slot separator - The separator to use for the breadcrumb item. This will only change the separator for this item. If
 * you want to change it for all items in the group, set the separator on `<hbr-breadcrumb>` instead.
 *
 * @part base - The component's internal wrapper.
 * @part label - The breadcrumb item's label.
 * @part prefix - The container that wraps the prefix slot.
 * @part suffix - The container that wraps the suffix slot.
 * @part separator - The container that wraps the separator slot.
 */
@Component({
	tag: "hbr-breadcrumb-item",
	styleUrl: "breadcrumb-item.scss",
	shadow: true,
})
export class HbrBreadcrumbItem {
	@Element() el: HTMLHbrBreadcrumbItemElement;
	/**
	 * Optional URL to direct the user to when the breadcrumb item is activated. When set, a link will be rendered
	 * internally. When unset, a button will be rendered instead.
	 */
	@Prop() href?: string;

	/** Tells the browser where to open the link. Only used when `href` is set. */
	@Prop() target?: "_blank" | "_parent" | "_self" | "_top";

	/** The `rel` attribute to use on the link. Only used when `href` is set. */
	@Prop() rel = "noreferrer noopener";

	/** Disabled attirbute for the button. */
	@Prop({ reflect: true }) disabled = false;

	/** Emitted when the slot label changes. */
	@Event({ eventName: "hbr-breadcrumb-change" })
	hbrBreadcrumbChange: EventEmitter;

	connectedCallback() {
		this.handleSlotChange = this.handleSlotChange.bind(this);
	}
	handleSlotChange() {
		this.hbrBreadcrumbChange.emit();
	}

	render() {
		const isLink = this.href ? true : false;
		const prefix = testSlot("prefix", this.el);
		const suffix = testSlot("suffix", this.el);
		return (
			<div
				part="base"
				class={`breadcrumb-item ${
					prefix
						? "breadcrumb-item--has-prefix"
						: suffix
						  ? "breadcrumb-item--has-suffix"
						  : ""
				}`}
			>
				<div part="clickable" class="breadcrumb-item__clickable">
					<span part="prefix" class="breadcrumb-item__prefix">
						<slot name="prefix" />
					</span>
					{/** Remove target and rel when undefined */}
					{isLink ? (
						<a
							part="label"
							class="breadcrumb-item__label breadcrumb-item__label--link"
							href={this.href}
							target={this.target ? this.target : ""}
							rel={this.target ? this.rel : ""}
						>
							<slot />
						</a>
					) : (
						<button
							disabled={this.disabled}
							part="label"
							type="button"
							class="breadcrumb-item__label breadcrumb-item__label--button"
						>
							<slot onSlotchange={this.handleSlotChange} />
						</button>
					)}

					<span part="suffix" class="breadcrumb-item__suffix">
						<slot name="suffix" />
					</span>
				</div>
				<span
					part="separator"
					class="breadcrumb-item__separator"
					aria-hidden="true"
					onClick={(event) => {
						event.stopPropagation();
					}}
				>
					<slot name="separator" />
				</span>
			</div>
		);
	}
}
